import boto3
import json
import time

client = boto3.client('logs')

log_group_name = 'test-log-group'
log_stream_name = 'test-log-stream'

def create_log_group_if_not_exists(client, log_group_name):
    try:
        client.describe_log_groups(logGroupNamePrefix=log_group_name)
    except client.exceptions.ResourceNotFoundException:
        client.create_log_group(logGroupName=log_group_name)

def create_log_stream_if_not_exists(client, log_group_name, log_stream_name):
    try:
        client.describe_log_streams(
            logGroupName=log_group_name,
            logStreamName=log_stream_name
        )
    except client.exceptions.ResourceNotFoundException:
        client.create_log_stream(
            logGroupName=log_group_name,
            logStreamName=log_stream_name
        )

create_log_group_if_not_exists(client, log_group_name)
create_log_stream_if_not_exists(client, log_group_name, log_stream_name)

structured_log = {
    'level': 'INFO',
    'message': 'Test structured log event',
    'timestamp': time.strftime('%Y-%m-%dT%H:%M:%S'),
    'service': 'example-service',
    'data': {'user_id': 123, 'action': 'login'}
}

log_event = {
    'timestamp': int(time.time() * 1000),
    'message': json.dumps(structured_log)
}

response = client.put_log_events(
    logGroupName=log_group_name,
    logStreamName=log_stream_name,
    logEvents=[log_event]
)

print('Log event sent:', response['nextSequenceToken'])
